import { useState } from "react";
import { FileDown, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { downloadInvoice } from "@/services/invoices.service";

interface InvoiceDownloadButtonProps {
  orderNumber: string;
  className?: string;
}

/** Downloads the order's proforma invoice (PDF) generated by the .NET service. */
export function InvoiceDownloadButton({ orderNumber, className }: InvoiceDownloadButtonProps) {
  const [status, setStatus] = useState<"idle" | "loading" | "error">("idle");
  const [error, setError] = useState<string>();

  async function handleClick() {
    setStatus("loading");
    setError(undefined);
    try {
      await downloadInvoice(orderNumber);
      setStatus("idle");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Fatura indirilemedi.");
      setStatus("error");
    }
  }

  const errorId = `invoice-error-${orderNumber}`;

  return (
    <span className={cn("inline-flex flex-col items-end", className)}>
      <button
        type="button"
        onClick={handleClick}
        disabled={status === "loading"}
        aria-describedby={status === "error" ? errorId : undefined}
        className="inline-flex items-center gap-1.5 rounded-full border border-ink-200 px-3 py-1.5 text-xs font-medium text-ink-600 transition-[border-color,color,transform] duration-150 hover:border-bronze-400 hover:text-bronze-600 active:scale-[0.97] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-gold-500 disabled:pointer-events-none disabled:opacity-60"
      >
        {status === "loading" ? (
          <Loader2 size={14} className="animate-spin" aria-hidden="true" />
        ) : (
          <FileDown size={14} aria-hidden="true" />
        )}
        {status === "loading" ? "Hazırlanıyor…" : "Fatura (PDF)"}
        <span className="sr-only"> — sipariş #{orderNumber}</span>
      </button>
      {status === "error" && (
        <span id={errorId} role="alert" className="mt-1 max-w-56 text-right text-[11px] leading-snug text-bronze-600">
          {error}
        </span>
      )}
    </span>
  );
}
